options(mc.cores=1L);source('cellchat_nichechat_fibro7/scripts/nichenet_common.R');setDTthreads(1);library(ggplot2);library(cowplot)
O<-'results/C5_Endothelial_NicheNet_spatial_v1';skill<-'/home/jinshengxi/.agents/skills/jins-routine-plotting';for(f in c('common/theme.R','common/palettes.R','common/export.R'))source(file.path(skill,f));jin_setup();theme_set(theme_classic(base_family='Arial',base_size=12))
nulls<-character();cowplot::set_null_device(function(width,height){f<-tempfile(fileext='.pdf');nulls<<-c(nulls,f);cairo_pdf(f,width=width,height=height,family='Arial')})
ex<-function(p,n,w=8,h=6){jin_export(p,file.path(O,'figures',n),width=w,height=h)}
a<-fread(file.path(O,'04_NicheNet_ligand_activity/all_program_activities.tsv'));for(nm in unique(a$program)){
 d<-a[program==nm & rank<=15];fwrite(d,file.path(O,'figures',paste0('A_',nm,'_data.tsv')),sep='\t');d[,test_ligand:=factor(test_ligand,levels=rev(test_ligand))];p<-ggplot(d,aes(aupr_corrected,test_ligand,fill=CellChat_supported))+geom_col(width=.7)+scale_fill_manual(values=c('FALSE'='#AAAAAA','TRUE'='#637BA8'),name='CellChat support')+labs(x='NicheNet corrected AUPR',y=NULL);ex(p,paste0('A_',nm))
}
l<-fread(file.path(O,'05_ligand_target_links/top10_links.tsv'));for(nm in unique(l$program)){
 d<-l[program==nm];if(!nrow(d))next;fwrite(d,file.path(O,'figures',paste0('B_',nm,'_data.tsv')),sep='\t');p<-ggplot(d,aes(target,ligand,fill=weight))+geom_tile()+scale_fill_viridis_c(name='Prior potential',guide=guide_colourbar(display='rectangles'))+theme(axis.text.x=element_text(angle=60,hjust=1))+labs(x=NULL,y=NULL);ex(p,paste0('B_',nm),12,6)
}
d<-fread(file.path(O,'08_patient_dataset_sensitivity/patient_bootstrap_LODO.tsv'));d<-d[omitted_dataset=='NONE' & top_fraction==.1 & ring==1 & role!='curated_program'];fwrite(d,file.path(O,'figures/E_patient_data.tsv'),sep='\t');p<-ggplot(d,aes(median_effect,ligand,colour=metric))+geom_vline(xintercept=0,linewidth=.4,colour='grey70')+geom_errorbarh(aes(xmin=ci_low,xmax=ci_high),height=.15,linewidth=.4,position=position_dodge(width=.5))+geom_point(position=position_dodge(width=.5))+facet_wrap(~metric,scales='free_x')+labs(x='Patient median effect (95% bootstrap CI)',y=NULL)+guides(colour='none');ex(p,'E_patient_effects',12,6)
d<-fread(file.path(O,'tables/spatial_effects.tsv'));d<-d[top_fraction==.1 & ring==1 & role!='curated_program'];fwrite(d,file.path(O,'figures/E_sections_data.tsv'),sep='\t');p<-ggplot(d,aes(dataset,adjusted_rho))+geom_hline(yintercept=0,linewidth=.4,colour='grey70')+geom_boxplot(outlier.shape=NA,linewidth=.4)+geom_point(position=position_jitter(width=.12,seed=123),size=1.2,colour='#637BA8')+facet_wrap(~ligand)+theme(axis.text.x=element_text(angle=60,hjust=1))+labs(x=NULL,y='Adjusted ligand–neighbor receptor Spearman');ex(p,'E_dataset_heterogeneity',13,8)
e<-fread(file.path(O,'06_CellChat_integration/full_evidence.tsv'));e<-e[!is.na(rank)&rank<=15];e<-unique(e[,.(test_ligand,program,rank,patient_condition_median,positive_patients,eligible_patients)]);fwrite(e,file.path(O,'figures/C_evidence_data.tsv'),sep='\t');p<-ggplot(e,aes(rank,patient_condition_median,label=test_ligand))+geom_point(colour='#637BA8',size=2)+geom_text(check_overlap=TRUE,hjust=-.1,size=3)+facet_wrap(~program)+labs(x='NicheNet rank',y='CellChat median strength (eligible patients)');ex(p,'C_evidence',12,6)
# Spatial panels use explicit within-section percentiles; raw values remain in the plot data.
for(f in list.files(file.path(O,'figures'),pattern='^D_.*_data.tsv.gz$',full.names=TRUE)){
 d<-fread(f);p<-ggplot(d,aes(x,y,colour=percentile))+geom_point(size=.45)+facet_wrap(~variable,nrow=1)+scale_y_reverse()+coord_fixed()+scale_colour_viridis_c(limits=c(0,1),name='Within-section\npercentile',guide=guide_colourbar(display='rectangles',barwidth=unit(3.2,'cm')))+theme_void(base_family='Arial',base_size=12)+theme(legend.position='bottom',strip.text=element_text(size=12));ex(p,sub('_data.tsv.gz$','',basename(f)),14,4)
}
unlink(nulls);cat('PLOTS_COMPLETE\n')
